// Prueba de envío: toma hasta CANTIDAD mails de Radar ya redactados y los manda
// a TU casilla (PARA), con copia oculta a contacto@ para que aparezcan en Enviados.
// No le escribe a ningún cliente y no toca la planilla.
const c = $('Config').first().json;
const BAJA = "Si no te interesa, respondé 'no' y no te escribo más.";
const tieneBaja = t => /no te escribo m[aá]s|no le escribo m[aá]s|no vuelvo a escribir|won'?t (write|email)|n[aã]o (te |lhe )?escrevo mais/i.test(t);
const para = String(c.PARA || '').trim();
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(para)) throw new Error('Poné tu mail en Config → PARA');
const copia = (String(c.MI_EMAIL || '').match(/[\w.+-]+@[\w.-]+/) || [''])[0];
const leads = $('Leer Leads').all().map(r => r.json)
  .filter(l => l.id && String(l.asunto || '').trim() && String(l.borrador || '').trim());
const orden = l => /^aprobado/.test(l.estado || '') ? 0 : 1;   // primero los que aprobaste
return leads.sort((a, b) => orden(a) - orden(b))
  .slice(0, Number(c.CANTIDAD) || 5)
  .map(l => { let t = String(l.borrador).trim(); if (!tieneBaja(t)) t += '\n\n' + BAJA;
    return { json: { para, copia,
      asunto: '[PRUEBA] ' + String(l.asunto).trim(),
      cuerpo: 'PRUEBA · Así le llega a ' + (l.nombre || 'el cliente') + ' (' + (l.email || 'sin mail') + '). ' +
        'A esa persona no se le mandó nada.\n\n────────\n\n' + t } }; });
